<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
Auth::requireLogin();
$pdo=Database::connection();
function dn(?string $v):string{$v=trim((string)$v);if($v==='')return '';$v=mb_strtolower($v,'UTF-8');$a=@iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$v);if($a!==false)$v=strtolower($a);return preg_replace('/[^a-z0-9]+/','',$v)??'';}
function dd(?string $v):string{return preg_replace('/\D+/','',(string)$v)??'';}
function ds(string $a,string $b):float{if($a===''||$b==='')return 0;if($a===$b)return 1;$m=max(strlen($a),strlen($b));return $m&&$m<=255?1-(levenshtein($a,$b)/$m):0;}
function score(array $a,array $b):array{$s=0;$r=[];$fa=dn($a['first_name']);$fb=dn($b['first_name']);$la=dn($a['last_name']);$lb=dn($b['last_name']);$exact=$fa!==''&&$la!==''&&$fa===$fb&&$la===$lb;if($exact){$s+=65;$r[]='exact dezelfde naam';}elseif($la!==''&&$la===$lb&&ds($fa,$fb)>=.84){$s+=45;$r[]='sterk gelijkende voornaam + zelfde familienaam';}elseif($fa!==''&&$fa===$fb&&ds($la,$lb)>=.88){$s+=40;$r[]='zelfde voornaam + sterk gelijkende familienaam';}
$ea=strtolower(trim((string)($a['email']??'')));$eb=strtolower(trim((string)($b['email']??'')));if($ea!==''&&$ea===$eb){$s+=35;$r[]='zelfde e-mailadres';}$ma=dd($a['mobile']??'');$mb=dd($b['mobile']??'');if(strlen($ma)>=7&&$ma===$mb){$s+=35;$r[]='zelfde GSM';}$ba=trim((string)($a['birth_date']??''));$bb=trim((string)($b['birth_date']??''));if($ba!==''&&$ba===$bb){$s+=30;$r[]='zelfde geboortedatum';}$aa=dn($a['address']??'').dn($a['postal_code']??'');$ab=dn($b['address']??'').dn($b['postal_code']??'');if(strlen($aa)>=6&&$aa===$ab){$s+=10;$r[]='zelfde adres';}return[$s,$r];}
$members=$pdo->query('SELECT m.*,(SELECT COUNT(*) FROM memberships x WHERE x.member_id=m.id) membership_count,(SELECT COUNT(*) FROM member_tags x WHERE x.member_id=m.id) tag_count FROM members m ORDER BY m.last_name,m.first_name,m.id')->fetchAll();$pairs=[];for($i=0,$n=count($members);$i<$n;$i++)for($j=$i+1;$j<$n;$j++){[$s,$r]=score($members[$i],$members[$j]);if($s>=40)$pairs[]=['a'=>$members[$i],'b'=>$members[$j],'score'=>$s,'reasons'=>$r,'confidence'=>$s>=80?'high':($s>=60?'medium':'low')];}usort($pairs,fn($a,$b)=>$b['score']<=>$a['score']);$filter=$_GET['confidence']??'all';if(!in_array($filter,['all','high','medium','low'],true))$filter='all';$visible=array_values(array_filter($pairs,fn($p)=>$filter==='all'||$p['confidence']===$filter));$counts=['high'=>0,'medium'=>0,'low'=>0];foreach($pairs as$p)$counts[$p['confidence']]++;
function mc(array$m):string{$details=[];if($m['birth_date']??'')$details[]='Geb. '.e($m['birth_date']);if($m['mobile']??'')$details[]=e($m['mobile']);if($m['email']??'')$details[]=e($m['email']);$ad=trim(($m['address']??'').' '.($m['postal_code']??'').' '.($m['city']??''));if($ad!=='')$details[]=e($ad);return '<div><a class="name" href="/member.php?id='.(int)$m['id'].'">'.e(($m['first_name']??'').' '.($m['last_name']??'')).'</a><div class="muted">'.e($m['member_number']?:'Geen lidnummer').' · ID '.(int)$m['id'].'</div><div class="details">'.implode('<br>',$details).'</div><div class="muted">'.(int)$m['membership_count'].' lidmaatschap(pen) · '.(int)$m['tag_count'].' tag(s)</div></div>';}
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Duplicaten - Heli One</title><style>body{font-family:Arial,sans-serif;background:#f5f6f8;margin:0;color:#171717}header{background:#111;color:#fff;padding:18px 28px;display:flex;justify-content:space-between}header a{color:#fff}main{max-width:1280px;margin:32px auto;padding:0 22px}.muted{color:#68707a}.notice{background:#eef4ff;padding:14px;border-radius:10px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.stat,.pair{background:#fff;border-radius:12px;padding:18px;box-shadow:0 4px 18px #0000000d}.stat strong{display:block;font-size:28px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.filters a{padding:9px 13px;border-radius:999px;background:#e8ebef;color:#222;text-decoration:none}.filters .active{background:#111;color:#fff}.pair{padding:0;margin:14px 0;overflow:hidden}.head{padding:13px 18px;background:#fafbfc;border-bottom:1px solid #eee;display:flex;justify-content:space-between;gap:12px}.compare{display:grid;grid-template-columns:1fr 1fr}.side{padding:20px}.side+.side{border-left:1px solid #eee}.name{font-size:18px;font-weight:800;color:#111;text-decoration:none}.details{line-height:1.5;margin:8px 0}.pill{padding:5px 9px;border-radius:999px;font-size:12px;font-weight:bold}.high{background:#ffe9e5}.medium{background:#fff1d7}.low{background:#eef1f4}@media(max-width:700px){.stats,.compare{grid-template-columns:1fr}.side+.side{border-left:0;border-top:1px solid #eee}}</style></head><body><header><strong>Heli One Members</strong><div><a href="/">Dashboard</a> · <a href="/logout.php">Afmelden</a></div></header><main><h1>Duplicaten controleren</h1><p class="muted">De controle is hoofdletterongevoelig en toont nu ook exacte naamduplicaten zonder e-mail of andere gegevens.</p><div class="notice"><strong>Controlemodus:</strong> er wordt nog niets verwijderd. Exact dezelfde voor- en familienaam wordt altijd als kandidaat getoond. Gelijkende namen verschijnen onder “Ruime controle”.</div><section class="stats"><div class="stat">Totaal<strong><?=count($pairs)?></strong></div><div class="stat">Hoge kans<strong><?=$counts['high']?></strong></div><div class="stat">Waarschijnlijk<strong><?=$counts['medium']?></strong></div><div class="stat">Ruime controle<strong><?=$counts['low']?></strong></div></section><div class="filters"><?php foreach(['all'=>'Alles','high'=>'Hoge kans','medium'=>'Waarschijnlijk','low'=>'Ruime controle'] as$k=>$v):?><a class="<?=$filter===$k?'active':''?>" href="/duplicates.php<?=$k==='all'?'':'?confidence='.$k?>"><?=$v?></a><?php endforeach;?></div><?php if(!$visible):?><div class="pair">Geen kandidaten in deze selectie.</div><?php endif;?><?php foreach($visible as$p):?><section class="pair"><div class="head"><div><span class="pill <?=$p['confidence']?>"><?=e($p['confidence']==='high'?'Hoge kans':($p['confidence']==='medium'?'Waarschijnlijk':'Ruime controle'))?></span> <strong>Score <?=$p['score']?></strong></div><div><?=e(implode(' · ',$p['reasons']))?></div></div><div class="compare"><div class="side"><?=mc($p['a'])?></div><div class="side"><?=mc($p['b'])?></div></div></section><?php endforeach;?></main></body></html>